<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Review moderation</h1><p>Reported reviews appear first. Hiding a review removes it from public food pages.</p></div></div>
<form class="toolbar" method="get" action="<?= h(app_url('admin.reviews')) ?>"><input type="hidden" name="r" value="admin.reviews"><div class="form-field"><label for="status">Review status</label><select id="status" name="status"><option value="">All reviews</option><?php foreach (['PUBLISHED','PENDING','HIDDEN'] as $candidate): ?><option value="<?= h($candidate) ?>"<?= $status===$candidate?' selected':'' ?>><?= h(ucfirst(strtolower($candidate))) ?></option><?php endforeach; ?></select></div><button class="button button-secondary" type="submit">Filter</button></form>
<?php if ($reviews): ?><div class="review-list"><?php foreach ($reviews as $review): ?><article class="review-card"><div class="spread"><div><strong><?= h($review['food_name']) ?></strong><div class="muted small"><?= h($review['student_name']) ?> · <?= h($review['vendor_name']) ?> · <?= h($review['order_number']) ?></div></div><span class="stars" aria-label="<?= (int)$review['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></span></div><?php if ($review['comment']): ?><p><?= nl2br(h($review['comment'])) ?></p><?php endif; ?><?php if (!empty($review['reports'])): ?><details class="report-details"><summary><?= count($review['reports']) ?> open review report<?= count($review['reports']) === 1 ? '' : 's' ?> — view reasons</summary><ul><?php foreach ($review['reports'] as $report): ?><li><strong><?= h($report['reporter']) ?></strong> · <?= h(format_datetime($report['created_at'])) ?><p><?= nl2br(h($report['reason'])) ?></p></li><?php endforeach; ?></ul></details><?php endif; ?><div class="spread"><div><?php $status=$review['status']; $badgeLabel=match ($status) { 'PENDING' => 'Pending moderation', 'PUBLISHED' => 'Published', 'HIDDEN' => 'Hidden', default => status_label($status) }; require APP_ROOT . '/views/components/status-badge.php'; ?><?php if ((int)$review['open_reports']>0): ?><span class="badge status-pending"><?= (int)$review['open_reports'] ?> open report<?= (int)$review['open_reports']===1?'':'s' ?></span><?php endif; ?></div><form method="post" action="<?= h(app_url('admin.review.status')) ?>" class="row-wrap"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><label class="sr-only" for="moderate-<?= (int)$review['id'] ?>">Review status</label><select id="moderate-<?= (int)$review['id'] ?>" name="status"><option value="PUBLISHED"<?= $review['status']==='PUBLISHED'?' selected':'' ?>>Published</option><option value="PENDING"<?= $review['status']==='PENDING'?' selected':'' ?>>Pending</option><option value="HIDDEN"<?= $review['status']==='HIDDEN'?' selected':'' ?>>Hidden</option></select><button class="button button-secondary button-small" type="submit">Save</button></form></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2>No reviews in this view</h2><p>Student reviews and reports will appear here.</p></div><?php endif; ?>
